entries[94535] = { ["name"] = "Grilled Dinosaur Haunch", ["text"] = "Use: Restores 21682 health and ( 5000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 10 mastery for 1 hour.\nSell Price:" }
