entries[94552] = { ["name"] = "Plans: Lightning Steel Ingot", ["text"] = "Binds when picked up\nUse: Teaches you how to create Lightning Steel Ingots.\nCreate a Lightning Steel Ingot from Ghost Iron Bars. In the process, you may gain additional knowledge of Ghost Iron, and discover a Blacksmithing plan you have yet to learn. This can only be done once a day.\nRequires Pandaria Blacksmithing (1)\n\nLightning Steel Ingot\nBinds when picked up\nCrafting Reagent\n\"Used by Blacksmiths in the creation of powerful items.\"\nSell Price:\nRequires Ghost Iron Bar (10)" }
