entries[94847] = { ["name"] = "Chief Engineer Jard's Journal", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (600)\n\"This journal was dropped by the well-known engineer Jard during his travels in Pandaria. Perhaps you'll find some interesting notes in it.\"\n<Right Click to Open>" }
