entries[94867] = { ["name"] = "Heart of the Thunder King", ["text"] = "Binds when picked up\nUnique\n\"A blackened, shriveled husk that nonetheless still throbs with a strange electric current.\"" }
entries[94880] = { ["name"] = "Schematic: Sky Golem", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to create the Sky Golem.\nRequires Engineering (600)\n\nSky Golem\nMount\n(Account-wide)\nUse: Teaches you how to ride the Sky Golem. This is a flying mount.\nMount a Sky Golem, allowing you to fly very fast. The claws are surprisingly delicate and herbalists can use them to pick herbs! This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"A glorious feat of engineering, the sky golem takes traditional shredder technology to a whole new level (and altitude!).\"\nProfession:\nEngineeringRequires Jard's Peculiar Energy Source (30), Living Steel (30)" }
entries[94893] = { ["name"] = "Schematic: Pierre", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to create Pierre.\nRequires Engineering (600)\n\nPierre\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss Pierre. If you give him a moment to heat up, he makes an excellent cooking fire.\nRequires level 1 to 80 ( 80)\nRequires Jard's Peculiar Energy Source (15), Living Steel (15)" }
entries[94894] = { ["name"] = "Schematic: Advanced Refrigeration Unit", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to create the ARU.\nRequires Engineering (600)\n\nAdvanced Refrigeration Unit\nBinds when equipped\n36 Slot Cooking Bag\nRequires Jard's Peculiar Energy Source (5), Living Steel (5)" }
