entries[95041] = { ["name"] = "Malevolent Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These cloud serpents have scales that... are the color of clouds, actually.\"\nLegacy" }
entries[95050] = { ["name"] = "The Brassiest Knuckle", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\nRequires any Horde race\nUse: Teleports you to the Brawl'gar Arena. (1 Hour Cooldown)\n\"Proof positive you pack a punch.\"" }
