entries[95052] = { ["name"] = "Arcane Propellant", ["text"] = "Binds when picked up\nUnique (60)\nUse: Consume an arcane focus to launch yourself forward. Can only be used during the Troves of the Thunder King scenario. (10 Sec Cooldown)\nRequires Kirin Tor Offensive\n- Revered\nSell Price:" }
entries[95053] = { ["name"] = "A Common Rock", ["text"] = "Binds when picked up\nUnique (10)\nUse: Can be used to distract an enemy or trigger a trap during the Troves of the Thunder King scenario. (10 Sec Cooldown)\nRequires Kirin Tor Offensive\n- Honored\nSell Price:" }
entries[95054] = { ["name"] = "Potion of Light Steps", ["text"] = "Binds when picked up\nUnique (5)\nUse: Can be used to levitate over tile traps, fall at a reduced speed, and walk on water during the Troves of the Thunder King scenario. Taking damage will break this effect. (10 Sec Cooldown)\nRequires Kirin Tor Offensive\n- Friendly\nSell Price:" }
entries[95055] = { ["name"] = "Frost Rune Trap", ["text"] = "Binds when picked up\nUnique (5)\nUse: Places a rune that will freeze the next hostile target to step on it for 20 sec. Only usable in the Troves of the Thunder King scenario. (10 Sec Cooldown)\nRequires Kirin Tor Offensive\n- Revered\nSell Price:" }
entries[95056] = { ["name"] = "Polymorphic Key", ["text"] = "Binds when picked up\nUnique (5)\nUse: Magically reshape the key to fit any Ancient Gate in the Thunder King's Citadel for the Troves of the Thunder King scenario. (5 Min Cooldown)\nRequires Kirin Tor Offensive\n- Exalted\nSell Price:" }
entries[95057] = { ["name"] = "Reins of the Thundering Cobalt Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Thundering Cobalt Cloud Serpent. This is a flying mount. Requires Cloud Serpent Riding from the Order of the Cloud Serpent.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This is a descendant of the irascible Nalak. Lightning erupts from its scales and arcs over the saddle. Dare you sit?\"\nDrop:\nNalak\nLocation:\nIsle of Thunder" }
entries[95059] = { ["name"] = "Clutch of Ji-Kun", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Although Ji-Kun feasted on the failed creations of mogu flesh-shapers, her progeny is willing to eat more pedestrian carcasses.\"\nDrop:\nJi-Kun\nZone:\nThrone of Thunder" }
